import{_ as s,l as i,o as r,c as l,v as a,p as n,x as t,d as c,i as p,S as u}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"cpufreq governor","description":"","frontmatter":{"title":"cpufreq governor","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cpufreq-governor.md","filePath":"cs/cpufreq-governor.md","lastUpdated":1789023840000}'),d={name:"cs/cpufreq-governor.md"};function h(f,e,_,m,q,g){const o=i("Mermaid");return r(),l("div",null,[e[1]||(e[1]=a('<h1 id="cpufreq-governor" tabindex="-1">cpufreq governor <a class="header-anchor" href="#cpufreq-governor" aria-label="Permalink to &quot;cpufreq governor&quot;">​</a></h1><div class="epigraph"><p>governor 根据利用率选 P-state：performance 钉高、powersave 钉低、schedutil 跟调度器的 util 走。</p><footer>—— 据 Linux CPUFreq 文档；ACPI P-state 直觉；[EAS](/cs/eas-scheduling) 为能耗先修</footer></div><p><a href="/cs/fairness-metrics">公平</a> 的实验被频率搅动。<a href="/cs/heterogeneous-core-sched">异构</a> 的容量随频变。缺口是 <strong>cpufreq</strong>：谁决定 MHz，而不是主板 BIOS 百科。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>硬件有离散频率。ondemand：高 util 跳频。schedutil：用 PELT util 直接映射。intel_pstate 可能绕过通用层。缺口：过渡延迟；与 <a href="/cs/napi">NAPI poll</a> 造成假 util；用户 <code>cpufreq-set</code> 与策略冲突。本课不把每家 MSR 列出。</p><p><span class="marginnote">boost/turbo 是更高 P-state，热墙会收回。对象是策略，不是电路。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>tick 或更新 util → governor 选 freq → 写 MSR 或 SCMI。对照 <a href="/cs/tx-path-qdisc">qdisc</a>：一个整形包，一个整形瓦特。对照 DL：实时任务常要 performance。对照 memcg：无关直接。</p>',8)),(r(),n(u,null,{default:t(()=>[p(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20UTIL%5B%22CPU%20%E5%88%A9%E7%94%A8%E7%8E%87%22%5D%20--%3E%20GOV%5B%22governor%22%5D%0A%20%20GOV%20--%3E%20F%5B%22%E9%80%89%E9%A2%91%E7%8E%87%22%5D%0A%20%20F%20--%3E%20HW%5B%22P-state%20%E7%94%9F%E6%95%88%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>governor 把能耗与延迟的旋钮交给策略，使同一调度器在插电/电池下行为不同。错误的 powersave 把 cyclictest max 打爆。不要写成电费课。与 EAS：选核与选频是一对，分开调会打架。</p><p>容器一般不能直接设主机 freq，只能靠自己的 util 间接。</p><p>实现上：intel_pstate 在 passive 模式才听 schedutil。boost 受热墙限制，瞬时频率不是承诺。无 tick 的隔离核 util 更新少，governor 会看错忙闲。 读法上只引用<a href="/cs/fairness-metrics">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「调度进阶 / 公平、实时与能耗」课序里，对象是 <strong>cpufreq governor</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 thermal 框架的全部 trip。不保证虚拟化 pstate 是真硬件。下一课更闲时：C-state。</p><p>版本字段会变，课序钉的是机制对象「cpufreq governor」，不是某一主线内核的结构体名。 后课默认：频率由 governor 跟踪 util。空闲核进哪一档 C-state，下一课 cpuidle。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>governor 把 util 映射到 P-state。</li><li>schedutil 与调度器共用 util。</li><li>cpuidle/C-state 是下一课。</li><li>出处：Linux CPUFreq；ACPI；EAS 文档。</li></ul>',11))])}const E=s(d,[["render",h]]);export{P as __pageData,E as default};
